from math import isqrt

class Solution:
    def reachNumber(self, target: int) -> int:
        target = abs(target)
        steps = (isqrt(8 * target + 1) - 1) // 2
        while steps * (steps + 1) // 2 < target or (steps * (steps + 1) // 2 - target) % 2:
            steps += 1
        return steps
